def energy_change(*,vector_fields=False):
    """Evaluate a small trial's energy change before summing corner values.

    Subtracting two float32 means loses small improvements and can collapse the
    line-search step at different iterations after a tiny input translation.
    Use edge increments instead: dn = 2 a.da + da.da + 2 b.db + db.db and
    dchi = ddet * (chi_new + chi_old) / (root_new + root_old). This is the
    same regularized energy, without subtracting nearly equal global totals.
    The caller still checks positive cells and the complete footprint.
    """
    name='Prochitecture Streets / Quad corner stable energy change v2'
    if vector_fields:name+=' / Native planar vectors v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    for key in ('Geometry','Candidate'):g.socket(key,'NodeSocketGeometry')
    g.socket('Delta','NodeSocketFloat',default=.01)
    g.socket('Change','NodeSocketFloat','OUTPUT')
    inp=g.node('NodeGroupInput')
    change=_energy_change_field(g,inp.outputs['Geometry'],inp.outputs['Candidate'],inp.outputs['Delta'],vector_fields=vector_fields)
    output=g.node('NodeGroupOutput');g.bind(change,output.inputs['Change']);return g.g


def _energy_change_field(g,old,new,delta,*,vector_fields=False):
    """Keep the stable comparison's operations and reduction order unchanged."""
    delta=g.math('MAXIMUM',delta,1e-8)
    planar=PlanarMath(g,vector=vector_fields)
    i=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);indices=[i]
    for shift in (1,-1):
        node=g.node('GeometryNodeOffsetCornerInFace');g.bind(i,node.inputs['Corner Index'])
        node.inputs['Offset'].default_value=shift;indices.append(node.outputs['Corner Index'])
    points=[];increments=[]
    for index in indices:
        node=g.node('GeometryNodeVertexOfCorner');g.bind(index,node.inputs['Corner Index'])
        a=planar.read(c._sample(g,old,g.position(),node.outputs['Vertex Index'],'FLOAT_VECTOR'))
        b=planar.read(c._sample(g,new,g.position(),node.outputs['Vertex Index'],'FLOAT_VECTOR'))
        points.append(a);increments.append(planar.sub(b,a))
    a=planar.sub(points[1],points[0]);b=planar.sub(points[2],points[0])
    da=planar.sub(increments[1],increments[0]);db=planar.sub(increments[2],increments[0])
    det=planar.cross(a,b)
    change=planar.cross(da,b)+planar.cross(a,db)+planar.cross(da,db)
    def denominator(d):
        root=g.math('SQRT',d*d+4.*delta*delta)
        chi=c.choose(g,g.math('LESS_THAN',d,0.),2.*delta*delta/g.math('MAXIMUM',root-d,1e-12),.5*(d+root))
        return root,chi
    r0,raw0=denominator(det);r1,raw1=denominator(det+change)
    h0=g.math('MAXIMUM',raw0,1e-12);h1=g.math('MAXIMUM',raw1,1e-12)
    dn=2.*planar.dot(a,da)+planar.dot(da,da)+2.*planar.dot(b,db)+planar.dot(db,db)
    unclamped=g.math('GREATER_THAN',raw0,1e-12)*g.math('GREATER_THAN',raw1,1e-12)
    # The original energy has a denominator floor. If a trial reaches it,
    # compare the actual clamped values instead of differentiating past it.
    dh=c.choose(g,unclamped,change*(h1+h0)/g.math('MAXIMUM',r1+r0,1e-12),h1-h0)
    energy0=(planar.dot(a,a)+planar.dot(b,b))/h0
    difference=(dn-energy0*dh)/h1
    return c._stat(g,old,difference,'Mean','CORNER')


