def replace_legacy_references(*,compact_state=False,captured_gradient=False):
    """Opt in existing shared call sites during a disposable candidate build.

    This never runs during evaluation or source editing. Both the library
    builder and saved-scene qualifier use this operation so the experimental
    candidate can be reproduced from packaged Python without patching a solver
    per fixture. Default construction remains unchanged until qualification.
    """
    previous=[group for group in bpy.data.node_groups if group.name.startswith(
        'Prochitecture Streets / Pinned curved quad descent v1') and
        ('Stable energy change v2' not in group.name or
         (compact_state and 'Compact iteration state v1' not in group.name) or
         (captured_gradient and 'Captured gradient state v1' not in group.name))]
    replacements=[]
    for group in previous:
        replacement=build(lazy_scalar='Independent scalar' in group.name,stable_difference=True,
                          compact_state=compact_state,captured_gradient=captured_gradient)
        users=group.users
        group.user_remap(replacement)
        replacements.append(dict(previous=group.name,candidate=replacement.name,users=users))
    return replacements
